"id": "AL-001",
"allergy": "penicillin",
"target": "class:penicillin",
"appliesIf": "any",
"severity": "AVOID",
"severityIfSevere": "",
"reason": "من عائلة البنسلين نفسها.",
"action": "لا يُعطى. اختر مضادًا حيويًا من عائلة أخرى بعد مراجعة الصيدلي.",
